BEGIN TRANSACTION;
CREATE TABLE activities (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        title TEXT NOT NULL,
        theme TEXT,
        activity_date TEXT,
        venue TEXT,
        duration_hours TEXT DEFAULT '8 Hours',
        trainer_name TEXT,
        trainer_position TEXT,
        target_notes TEXT,
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE activity_attendees (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        activity_id INTEGER NOT NULL REFERENCES activities(id) ON DELETE CASCADE,
        move_roster_id INTEGER REFERENCES move_roster(id) ON DELETE SET NULL,
        full_name TEXT NOT NULL,
        position TEXT,
        gender TEXT DEFAULT 'M',
        civil_status TEXT DEFAULT 'Married',
        office TEXT,
        contact_number TEXT,
        is_present INTEGER DEFAULT 0,
        check_in_time TEXT,
        notes TEXT
    );
CREATE TABLE activity_facilitators (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    activity_id INTEGER NOT NULL REFERENCES activities(id) ON DELETE CASCADE,
    move_roster_id INTEGER REFERENCES move_roster(id) ON DELETE SET NULL,
    full_name TEXT NOT NULL,
    role_title TEXT DEFAULT 'Facilitator',
    position TEXT,
    office TEXT,
    gender TEXT DEFAULT 'M',
    civil_status TEXT DEFAULT 'Married',
    contact_number TEXT,
    is_present INTEGER DEFAULT 1,
    check_in_time TEXT,
    notes TEXT
);
CREATE TABLE issued_certificates (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        activity_id INTEGER REFERENCES activities(id) ON DELETE CASCADE,
        attendee_id INTEGER REFERENCES activity_attendees(id) ON DELETE CASCADE,
        cert_type TEXT NOT NULL, -- 'participation', 'appearance', 'appreciation'
        serial_no TEXT UNIQUE,
        signatory_1_id INTEGER REFERENCES signatories(id),
        signatory_2_id INTEGER REFERENCES signatories(id),
        signatory_3_id INTEGER REFERENCES signatories(id),
        issued_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE move_roster (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        full_name TEXT NOT NULL,
        position TEXT,
        gender TEXT DEFAULT 'M',
        civil_status TEXT DEFAULT 'Married',
        office TEXT,
        contact_number TEXT,
        role_title TEXT DEFAULT 'Member',
        is_member INTEGER DEFAULT 1,
        is_officer INTEGER DEFAULT 0,
        is_committee INTEGER DEFAULT 0,
        is_participant INTEGER DEFAULT 0,
        notes TEXT
    );
CREATE TABLE municipal_employees_search_pool (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        orig_no TEXT,
        full_name TEXT NOT NULL,
        position TEXT,
        gender TEXT DEFAULT 'M',
        civil_status TEXT DEFAULT 'Married',
        office TEXT,
        appointment TEXT DEFAULT 'PERMANENT',
        contact_number TEXT
    );
CREATE TABLE signatories (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        name TEXT NOT NULL,
        title TEXT NOT NULL,
        office TEXT,
        signature_image TEXT,
        is_default INTEGER DEFAULT 0
    );
CREATE UNIQUE INDEX idx_activity_attendees_unique ON activity_attendees(activity_id, UPPER(TRIM(full_name)));
CREATE UNIQUE INDEX idx_activity_facilitators_unique 
ON activity_facilitators(activity_id, UPPER(TRIM(full_name)));
DELETE FROM "sqlite_sequence";
COMMIT;
